const ctx = $input.first().json;
const ct = ctx.current_task || {};
const chain = ctx.ancestor_chain || [];
const leaves = ctx.linked_doc_leaves || [];

const lines = [];
lines.push('Jesteś asystentem AI wspierającym zespół Haxe. Wykonaj poniższe zadanie rzetelnie.');
lines.push('');
lines.push('# Zadanie');
lines.push(ct.name || '(bez nazwy)');
if (ct.description) { lines.push(''); lines.push(ct.description); }

if (chain.length) {
  lines.push('');
  lines.push('# Kontekst nadrzędny (od najogólniejszego do najbliższego)');
  for (const a of chain.slice().reverse()) {
    lines.push('');
    lines.push('## ' + (a.name || ''));
    if (a.description) lines.push(a.description);
  }
}

if (leaves.length) {
  lines.push('');
  lines.push('# Szczegółowe wytyczne');
  for (const l of leaves) { lines.push('- ' + (l.name || '')); if (l.content) lines.push(l.content); }
}

lines.push('');
lines.push('Przygotuj wynik dla powyższego zadania.');

const prompt = lines.join('\n');
return [{ json: { prompt, importance: ctx.importance || '', sensitivity: 'unknown', task_type: '' } }];
